/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `after_insert_arrange` AFTER INSERT ON `arrange` FOR EACH ROW BEGIN
    DECLARE count INT;
    SELECT COUNT(*) INTO count FROM arrangement WHERE ar_id = NEW.ar_id;
    IF count = 0 THEN
        INSERT INTO arrangement (ar_id, ar_time) VALUES (NEW.ar_id, NEW.ar_time);
    END IF;
END */;;
