INSERT INTO `emr_template` VALUES (1,'上感标准化病历模板',NULL,'咳嗽、咳痰、发热{天数}天','患者于{天数}天前受凉后出现咳嗽、咳痰，为{痰性质}痰，伴发热，体温最高达{体温}℃。伴咽痛、鼻塞、流涕，无胸闷气促，无腹痛腹泻。','既往体健，否认高血压、糖尿病等慢性病史。否认药物及食物过敏史。','T {体温}℃，P {脉搏}次/分，R {呼吸}次/分，BP {血压}mmHg。咽部充血，扁桃体{肿大情况}肿大。双肺呼吸音清，未闻及干湿啰音。','急性上呼吸道感染','1. 注意休息，多饮水，清淡饮食。2. 对症治疗：退热、止咳化痰。3. 如症状加重或持续不缓解，及时复诊。','2026-06-22 23:44:09','内科','202601'),(2,'高血压病历模板',NULL,'反复头晕、头痛{天数}天，血压升高','患者近{天数}天反复出现头晕、头痛，活动后明显，休息后可缓解。自测血压波动在{收缩压}-{舒张压}mmHg之间。伴心悸、胸闷，无恶心呕吐。','既往高血压病史{年数}年，最高血压{最高血压}mmHg。否认糖尿病史。','BP {血压}mmHg，心率{心率}次/分。神清，心肺听诊无明显异常。','高血压病{级别}级','1. 低盐低脂饮食，控制体重，适度运动。2. 规律服用降压药物。3. 每日监测血压，定期门诊复诊。','2026-06-22 23:44:09','内科','202601'),(3,'糖尿病病历模板',NULL,'口干、多饮、多尿{天数}天','患者近{天数}天出现口干、多饮、多尿症状，每日饮水量约{水量}ml，夜尿{夜尿次数}次/晚。伴体重下降约{体重下降}kg。','既往糖尿病史{年数}年。否认高血压病史。','神清，体型{体型}。心肺听诊无明显异常。空腹血糖{空腹血糖}mmol/L，餐后2h血糖{餐后血糖}mmol/L。','2型糖尿病','1. 糖尿病饮食，控制总热量摄入。2. 规律服用降糖药物。3. 监测血糖，定期复诊。4. 适当运动。','2026-06-22 23:44:09','内科','202601'),(4,'肺炎病历模板',NULL,'发热、咳嗽、咳痰{天数}天','患者{天数}天前出现发热，体温最高{体温}℃，伴咳嗽咳痰，为{痰性质}痰，量中。伴胸闷、气促。','既往体健，否认慢性病史。','T {体温}℃，神清，呼吸{呼吸}次/分。双肺呼吸音粗，可闻及{啰音性质}。','社区获得性肺炎','1. 抗生素抗感染治疗。2. 止咳化痰对症治疗。3. 注意休息，多饮水。4. 疗程{疗程}天后复查。','2026-06-22 23:44:09','呼吸内科','202601'),(5,'冠心病病历模板',NULL,'胸闷、胸痛{天数}天，活动后加重','患者{天数}天前出现胸闷、胸痛，位于胸骨后，呈压榨样，向左上肢放射，持续{持续时间}分钟，休息后缓解。活动后加重。','既往高血压病史{年数}年。否认糖尿病史。吸烟{烟龄}年。','BP {血压}mmHg。心率{心率}次/分，律齐。心音低钝。','冠状动脉粥样硬化性心脏病','1. 抗血小板、调脂稳定斑块治疗。2. 扩冠、改善心肌供血。3. 控制血压。4. 建议冠脉造影检查。','2026-06-22 23:44:09','心血管内科','202601'),(6,'胃炎病历模板',NULL,'上腹痛、反酸、嗳气{天数}天','患者{天数}天前出现上腹部隐痛，伴反酸、嗳气，饭后加重。无呕血黑便。','既往胃病史{年数}年，否认药物过敏史。','腹软，上腹部轻压痛，无反跳痛。','慢性胃炎','1. 抑酸保护胃黏膜治疗。2. 清淡饮食，避免辛辣刺激。3. Hp检测，必要时根除治疗。4. 定期复查胃镜。','2026-06-22 23:44:09','消化内科','202601'),(7,'儿科发热模板',NULL,'发热{天数}天，体温最高{体温}℃','患儿{天数}天前无明显诱因出现发热，体温最高{体温}℃，热型不规则。伴咽痛、流涕、轻咳。精神可，纳差。','既往体健，否认药物过敏史。','T {体温}℃。咽部充血，扁桃体I-II度肿大。心肺听诊(-)。','急性上呼吸道感染','1. 退热对症治疗（体温>38.5℃时使用退热药）。2. 多饮水，注意休息。3. 清淡易消化饮食。4. 若持续发热或出现其他症状及时复诊。','2026-06-22 23:44:09','儿科','202601'),(8,'高血压急诊模板',NULL,'剧烈头痛、视物模糊、恶心呕吐{天数}小时','患者{天数}小时前突发剧烈头痛，视物模糊，伴恶心呕吐{次数}次。自测血压高达{收缩压}/{舒张压}mmHg。','既往高血压病史{年数}年，最高血压{最高血压}mmHg。','BP {血压}mmHg，神清，瞳孔等大等圆。心肺听诊无明显异常。','高血压急症','1.立即降压治疗，硝苯地平10mg舌下含服。2.心电监护。3.完善头颅CT排除脑出血。4.收入院治疗。','2026-07-04 23:36:39','心血管内科','202601'),(9,'冠心病急诊模板',NULL,'持续性胸痛{分钟}分钟，向左上肢放射','患者{分钟}分钟前无明显诱因出现胸骨后压榨样疼痛，向左上肢放射，伴大汗淋漓、面色苍白。含服硝酸甘油不缓解。','既往冠心病史{年数}年，高血压病史。吸烟{烟龄}年。','BP {血压}mmHg，HR {心率}次/分。心音低钝，可闻及奔马律。','急性冠脉综合征（STEMI待排）','1.立即心电监护。2.吸氧4L/min。3.阿司匹林300mg嚼服+替格瑞洛180mg负荷。4.急诊PCI术前准备。','2026-07-04 23:36:39','心血管内科','202601'),(10,'慢性阻塞性肺疾病模板',NULL,'反复咳痰喘{年数}年，加重{天数}天','患者{年数}年前开始反复出现咳嗽咳痰，每年发作{次数}次。近{天数}天上述症状加重，伴气促、呼吸困难，稍活动即感喘息。','COPD病史{年数}年，吸烟{烟龄}年，每日{支数}支。','T {体温}℃，R {呼吸}次/分，SpO2 {氧饱和度}%。桶状胸，双肺呼吸音低，可闻及湿啰音和哮鸣音。','慢性阻塞性肺疾病急性加重','1.吸氧（低流量1-2L/min）。2.支气管舒张剂（沙丁胺醇雾化）。3.糖皮质激素静脉滴注。4.抗生素抗感染治疗。5.祛痰止咳。','2026-07-04 23:36:39','呼吸内科','202601'),(11,'急性胰腺炎模板',NULL,'上腹部剧烈疼痛{小时}小时，向后背放射','患者{小时}小时前进食油腻食物后出现上腹部持续性剧痛，向后背放射，伴恶心呕吐，腹胀，无排便排气。','既往胆结石病史{年数}年，否认高血压糖尿病。','T {体温}℃，腹膨隆，上腹部压痛明显，反跳痛(+)，Murphy征可疑。肠鸣音减弱。','急性胰腺炎（水肿型？）','1.禁食水、胃肠减压。2.抑制胰酶分泌（生长抑素）。3.液体复苏、纠正电解质紊乱。4.镇痛。5.完善CT、血尿淀粉酶检查。','2026-07-04 23:36:39','消化内科','202601'),(12,'脑梗死模板',NULL,'突发口齿不清、右侧肢体无力{小时}小时','患者{小时}小时前安静状态下突发口齿不清，右侧肢体无力，持物不能，行走困难。无恶心呕吐，无意识障碍。','既往高血压{年数}年，糖尿病{年数}年，房颤史{年数}年。','BP {血压}mmHg，神清，言语含糊。右侧鼻唇沟变浅，伸舌右偏。右侧上下肢肌力{肌力}级，右侧巴氏征(+)。','急性脑梗死','1.急诊头颅CT排除出血。2.完善NIHSS评分。3.若在时间窗内(4.5h)评估溶栓。4.抗血小板治疗。5.他汀类药物。6.康复治疗。','2026-07-04 23:36:39','神经内科','202601'),(13,'泌尿系感染模板',NULL,'尿频、尿急、尿痛{天数}天','患者{天数}天前出现尿频（每日{次数}余次）、尿急、尿痛，伴下腹部坠胀感。无发热，无肉眼血尿。','既往体健，否认药物过敏史。','T {体温}℃，双肾区无叩击痛，耻骨上轻压痛。','急性下尿路感染','1.抗生素治疗（左氧氟沙星0.5g qd×7天）。2.多饮水，保持尿量。3.碱化尿液。4.完善尿常规+中段尿培养。','2026-07-04 23:36:39','泌尿外科','202601'),(14,'颈椎病模板',NULL,'颈肩部疼痛伴上肢麻木{天数}天','患者{天数}天前无明显诱因出现颈肩部酸痛，放射至右上臂及前臂，伴手指麻木。低头工作后加重。','既往长期伏案工作{年数}年。','颈椎活动受限，颈{节段}棘突旁压痛，压顶试验(+)，右侧臂丛神经牵拉试验(+)。','颈椎病（神经根型）','1.颈椎制动，避免长时间低头。2.非甾体抗炎药（塞来昔布）。3.甲钴胺营养神经。4.物理治疗（牵引、理疗）。5.必要时MRI检查。','2026-07-04 23:36:39','骨科','202601'),(15,'湿疹模板',NULL,'全身皮疹伴瘙痒{天数}天','患者{天数}天前无明显诱因出现躯干、四肢红斑、丘疹，伴剧烈瘙痒，搔抓后出现渗液。反复发作。','既往过敏史：花粉、尘螨过敏。','躯干四肢可见对称分布红斑、丘疹、抓痕，部分融合成片，有少量渗液。','湿疹（急性期）','1.外用糖皮质激素药膏。2.口服抗组胺药（氯雷他定10mg qd）。3.避免搔抓和热水烫洗。4.保湿护肤。5.忌食辛辣刺激食物。','2026-07-04 23:36:39','皮肤科','202601');
/*!40000 ALTER TABLE `emr_template` ENABLE KEYS */;
UNLOCK TABLES;

