--
-- Table structure for table `notification`
--

DROP TABLE IF EXISTS `notification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification` (
  `n_id` int NOT NULL AUTO_INCREMENT,
  `p_id` int DEFAULT NULL COMMENT '患者ID',
  `d_id` char(6) DEFAULT NULL COMMENT '医生ID',
  `n_type` varchar(30) DEFAULT NULL COMMENT '通知类型(payment/result/refund/pickup/followup)',
  `n_title` varchar(200) DEFAULT NULL COMMENT '通知标题',
  `n_content` text COMMENT '通知内容',
  `n_is_read` tinyint DEFAULT NULL COMMENT '已读状态(0=未读 1=已读)',
  `n_create_time` datetime DEFAULT NULL COMMENT '创建时间',
  PRIMARY KEY (`n_id`),
