  `o_end` varchar(255) DEFAULT NULL COMMENT '结束时间',
  `o_state` int DEFAULT NULL COMMENT '订单状态(0=已挂号 1=已分诊 2=就诊中 3=已开处方 4=待缴费 5=已缴费 6=已发药 7=已完成)',
