  `o_cancel_reason` varchar(500) DEFAULT NULL COMMENT '取消原因',
  `o_missed` tinyint DEFAULT NULL COMMENT '是否爽约(0=否 1=是)',
  PRIMARY KEY (`o_id`) USING BTREE,
