INSERT INTO `outpatient_emr` VALUES (100,21001,1001,'D24001','测试头痛','患者1周前无明显诱因出现头痛，呈持续性钝痛，伴有头晕，无恶心呕吐','既往高血压病史3年，规律服药','T 36.5℃ P 78次/分 R 18次/分 BP 145/90mmHg，神志清楚','测试诊断','1.继续口服硝苯地平控释片 30mg qd；2.加用氟桂利嗪 5mg qn；3.低盐低脂饮食，监测血压',NULL,NULL,NULL,'2026-07-04 09:15:00','2026-07-04 23:33:17'),(101,21002,1002,'D24029','咳嗽咳痰1周','患者1周前受凉后出现咳嗽，咳黄痰，伴咽痛发热，最高体温38.5℃','既往体健，无药物过敏史','T 38.2℃ P 88次/分 咽部充血，双肺呼吸音粗，未闻及干湿啰音','急性支气管炎','1.阿莫西林胶囊 0.5g tid×7天；2.复方甘草口服液 10ml tid；3.多饮水，注意休息',NULL,NULL,NULL,'2026-07-04 09:20:00','2026-07-04 09:35:00'),(102,21003,1003,'D24002','发热2天','患者2天前无明显诱因出现发热，体温最高39.2℃，伴寒战、肌肉酸痛','既往糖尿病史5年','T 39.0℃ 咽部充血，扁桃体Ⅱ°肿大','急性化脓性扁桃体炎；2型糖尿病','1.头孢克肟颗粒 50mg bid；2.布洛芬缓释胶囊 0.3g prn；3.监测血糖',NULL,NULL,NULL,'2026-07-04 10:00:00','2026-07-04 10:15:00'),(103,21004,1004,'D24003','腹痛腹泻3天','患者3天前食用不洁食物后出现腹痛，呈阵发性绞痛，伴腹泻，每日5-6次','既往体健','T 37.8℃ 腹软，脐周压痛，肠鸣音活跃','急性胃肠炎','1.蒙脱石散 3g tid；2.口服补液盐；3.清淡饮食',NULL,NULL,NULL,'2026-07-04 10:30:00','2026-07-04 10:45:00'),(104,21005,1005,'D24034','胸闷气促1月','患者近1月出现活动后胸闷、气促，休息后可缓解，伴双下肢轻度水肿','既往冠心病史8年，支架植入术后','T 36.8℃ P 92次/分 BP 130/85mmHg，双肺底湿啰音，双踝部轻度水肿','慢性心力衰竭（NYHAⅡ-Ⅲ级）；冠状动脉支架植入术后','1.继续口服呋塞米20mg qd+螺内酯20mg qd；2.建议心脏超声、BNP检查',NULL,NULL,NULL,'2026-07-04 11:00:00','2026-07-04 11:20:00'),(105,21006,1006,'D24004','反酸烧心2月','患者近2月反复出现反酸、烧心，伴嗳气，餐后加重','既往体健，有吸烟饮酒史','T 36.6℃ 腹软，上腹部轻压痛','胃食管反流病','1.奥美拉唑20mg qd×4周；2.建议胃镜检查；3.戒烟酒，避免辛辣食物',NULL,NULL,NULL,'2026-07-04 14:00:00','2026-07-04 23:41:03'),(106,6251,1001,'D24001','颈肩部疼痛伴上肢麻木{天数}天','患者{天数}天前无明显诱因出现颈肩部酸痛，放射至右上臂及前臂，伴手指麻木。低头工作后加重。','既往长期伏案工作{年数}年。','颈椎活动受限，颈{节段}棘突旁压痛，压顶试验(+)，右侧臂丛神经牵拉试验(+)。','颈椎病（神经根型）','1.颈椎制动，避免长时间低头。2.非甾体抗炎药（塞来昔布）。3.甲钴胺营养神经。4.物理治疗（牵引、理疗）。5.必要时MRI检查。',NULL,NULL,NULL,'2026-07-04 23:30:37','2026-07-04 23:56:29'),(107,21008,1012,'D24001','发热{天数}天，体温最高{体温}℃','患儿{天数}天前无明显诱因出现发热，体温最高{体温}℃，热型不规则。伴咽痛、流涕、轻咳。精神可，纳差。','既往体健，否认药物过敏史。','T {体温}℃。咽部充血，扁桃体I-II度肿大。心肺听诊(-)。','急性上呼吸道感染','1. 退热对症治疗（体温>38.5℃时使用退热药）。2. 多饮水，注意休息。3. 清淡易消化饮食。4. 若持续发热或出现其他症状及时复诊。',NULL,NULL,NULL,'2026-07-04 23:40:27','2026-07-04 23:49:53'),(110,2736,1001,'D24001','test','患者{天数}天前无明显诱因出现颈肩部酸痛，放射至右上臂及前臂，伴手指麻木。低头工作后加重。','既往长期伏案工作{年数}年。','颈椎活动受限，颈{节段}棘突旁压痛，压顶试验(+)，右侧臂丛神经牵拉试验(+)。','test','1.颈椎制动，避免长时间低头。2.非甾体抗炎药（塞来昔布）。3.甲钴胺营养神经。4.物理治疗（牵引、理疗）。5.必要时MRI检查。',NULL,NULL,NULL,'2026-07-05 00:37:58','2026-07-05 00:54:01'),(111,2490,1002,'D24002','突发口齿不清、右侧肢体无力{小时}小时','患者{小时}小时前安静状态下突发口齿不清，右侧肢体无力，持物不能，行走困难。无恶心呕吐，无意识障碍。','既往高血压{年数}年，糖尿病{年数}年，房颤史{年数}年。','BP {血压}mmHg，神清，言语含糊。右侧鼻唇沟变浅，伸舌右偏。右侧上下肢肌力{肌力}级，右侧巴氏征(+)。','急性脑梗死','1.急诊头颅CT排除出血。2.完善NIHSS评分。3.若在时间窗内(4.5h)评估溶栓。4.抗血小板治疗。5.他汀类药物。6.康复治疗。',NULL,NULL,NULL,'2026-07-05 08:36:27','2026-07-05 08:39:42'),(112,2529,1001,'D24001','全身皮疹伴瘙痒{天数}天','患者{天数}天前无明显诱因出现躯干、四肢红斑、丘疹，伴剧烈瘙痒，搔抓后出现渗液。反复发作。','既往过敏史：花粉、尘螨过敏。','躯干四肢可见对称分布红斑、丘疹、抓痕，部分融合成片，有少量渗液。','湿疹（急性期）','1.外用糖皮质激素药膏。2.口服抗组胺药（氯雷他定10mg qd）。3.避免搔抓和热水烫洗。4.保湿护肤。5.忌食辛辣刺激食物。',NULL,NULL,NULL,'2026-07-05 08:37:06','2026-07-05 08:44:43'),(113,5520,1001,'D24001','全身皮疹伴瘙痒{天数}天','患者{天数}天前无明显诱因出现躯干、四肢红斑、丘疹，伴剧烈瘙痒，搔抓后出现渗液。反复发作。','既往过敏史：花粉、尘螨过敏。','躯干四肢可见对称分布红斑、丘疹、抓痕，部分融合成片，有少量渗液。','湿疹（急性期）','1.外用糖皮质激素药膏。2.口服抗组胺药（氯雷他定10mg qd）。3.避免搔抓和热水烫洗。4.保湿护肤。5.忌食辛辣刺激食物。',NULL,NULL,NULL,'2026-07-05 09:17:33','2026-07-05 09:17:33'),(114,8624,1010,'D24001','尿频、尿急、尿痛{天数}天','患者{天数}天前出现尿频（每日{次数}余次）、尿急、尿痛，伴下腹部坠胀感。无发热，无肉眼血尿。','既往体健，否认药物过敏史。','T {体温}℃，双肾区无叩击痛，耻骨上轻压痛。','急性下尿路感染','1.抗生素治疗（左氧氟沙星0.5g qd×7天）。2.多饮水，保持尿量。3.碱化尿液。4.完善尿常规+中段尿培养。',NULL,NULL,NULL,'2026-07-05 11:31:48','2026-07-05 11:31:48'),(116,2237,1002,'D24001','尿频、尿急、尿痛{天数}天','患者{天数}天前出现尿频（每日{次数}余次）、尿急、尿痛，伴下腹部坠胀感。无发热，无肉眼血尿。','既往体健，否认药物过敏史。','T {体温}℃，双肾区无叩击痛，耻骨上轻压痛。','急性下尿路感染','1.抗生素治疗（左氧氟沙星0.5g qd×7天）。2.多饮水，保持尿量。3.碱化尿液。4.完善尿常规+中段尿培养。',NULL,NULL,NULL,'2026-07-05 11:46:35','2026-07-05 11:46:35'),(117,2066,1001,'D24004','全身皮疹伴瘙痒{天数}天','患者{天数}天前无明显诱因出现躯干、四肢红斑、丘疹，伴剧烈瘙痒，搔抓后出现渗液。反复发作。','既往过敏史：花粉、尘螨过敏。','躯干四肢可见对称分布红斑、丘疹、抓痕，部分融合成片，有少量渗液。','湿疹（急性期）','1.外用糖皮质激素药膏。2.口服抗组胺药（氯雷他定10mg qd）。3.避免搔抓和热水烫洗。4.保湿护肤。5.忌食辛辣刺激食物。',NULL,NULL,NULL,'2026-07-05 12:12:20','2026-07-05 12:12:20');
