  `p_state` int DEFAULT NULL COMMENT '状态',
  `p_birthday` varchar(255) DEFAULT NULL COMMENT '出生日期',
  `p_age` int DEFAULT NULL COMMENT '年龄',
  `p_insurance_id` varchar(50) DEFAULT NULL COMMENT '医保卡号',
  `p_insurance_type` varchar(30) DEFAULT NULL COMMENT '医保类型',
  `p_contact_person` varchar(100) DEFAULT NULL COMMENT '联系人',
  `p_contact_phone` varchar(20) DEFAULT NULL COMMENT '联系人电话',
  `p_address` varchar(255) DEFAULT NULL COMMENT '地址',
