  `p_blacklisted` tinyint DEFAULT NULL COMMENT '是否黑名单(0=否 1=是)',
  `p_tags` varchar(200) DEFAULT NULL COMMENT '患者标签',
  PRIMARY KEY (`p_id`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='患者表';
